-- descripciones que faltaban: platos de gastronomía y espacios naturales
UPDATE entidades SET descripcion='Especialidad gastronómica típica de ' || (SELECT m.nombre FROM municipios m WHERE m.codigo_ine=entidades.codigo_ine) || ' (' || (SELECT m.provincia FROM municipios m WHERE m.codigo_ine=entidades.codigo_ine) || ').'
WHERE tipo='gastronomia' AND fuente='excel_curado' AND (descripcion IS NULL OR length(descripcion)<15);
UPDATE entidades SET descripcion='Espacio natural y paraje para visitar en ' || (SELECT m.nombre FROM municipios m WHERE m.codigo_ine=entidades.codigo_ine) || ' (' || (SELECT m.provincia FROM municipios m WHERE m.codigo_ine=entidades.codigo_ine) || ').'
WHERE tipo='espacio' AND fuente='inventario_naturaleza_pdf' AND (descripcion IS NULL OR length(descripcion)<15);
UPDATE entidades SET descripcion=COALESCE(NULLIF(descripcion,''), 'Lugar de interés en ' || (SELECT m.nombre FROM municipios m WHERE m.codigo_ine=entidades.codigo_ine) || '.')
WHERE (descripcion IS NULL OR length(descripcion)<15) AND fuente IN ('inventario_oleoturismo_pdf','wikidata_museos');
